from fastapi import FastAPI, Query, Header, Cookie
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

app = FastAPI()

class QueryModel(BaseModel):
    q: str = Field(alias="query_param")

@app.get("/query")
def read_query(params: QueryModel = Query()):
    return params

class HeaderModel(BaseModel):
    h: str = Field(alias="header_param")

@app.get("/header")
def read_header(params: HeaderModel = Header()):
    return params

class CookieModel(BaseModel):
    c: str = Field(alias="cookie_param")

@app.get("/cookie")
def read_cookie(params: CookieModel = Cookie()):
    return params

client = TestClient(app)

def test_query_alias():
    # Issue 1: Value is extracted by alias, but put into values with key field.name
    # Should work if fixed
    response = client.get("/query", params={"query_param": "value"})
    assert response.status_code == 200
    assert response.json() == {"q": "value"}

def test_query_name_extra():
    # Issue 2: If we pass the value by name, it should be an extra parameter
    # and thus cause a validation error (if extra='forbid') or just be ignored.
    # But the problem statement says "the input field will not contain the extra parameter (passed by name)".
    # This refers to the validation error's input.

    # To test this, we need a model that forbids extra fields.
    class QueryModelForbid(BaseModel):
        q: str = Field(alias="query_param")
        class Config:
            extra = "forbid"

    @app.get("/query_forbid")
    def read_query_forbid(params: QueryModelForbid = Query()):
        return params

    # Pass by name 'q' instead of alias 'query_param'
    response = client.get("/query_forbid", params={"q": "value"})
    assert response.status_code == 422
    # The error should contain 'q' in the input
    # Let's check the response body
    print(response.json())
    # We expect 'q' to be in the input of the error
    # The error should be something like:
    # {
    #   "detail": [
    #     {
    #       "loc": ["query", "q"],
    #       "msg": "extra fields not permitted",
    #       "type": "value_error.extra",
    #       "ctx": {"extra": "q"},
    #       "input": {"q": "value"}
    #     }
    #   ]
    # }
    # If 'q' was in processed_keys, it would be removed from params_to_process,
    # and thus not present in the input of the validation error.

    # Let's check if 'q' is in the input
    errors = response.json()["detail"]
    # Find the error for 'q'
    q_error = next((e for e in errors if e["loc"][-1] == "q"), None)
    assert q_error is not None
    assert "q" in q_error["input"]

def test_header_alias():
    response = client.get("/header", headers={"header_param": "value"})
    assert response.status_code == 200
    assert response.json() == {"h": "value"}

def test_cookie_alias():
    response = client.get("/cookie", cookies={"cookie_param": "value"})
    assert response.status_code == 200
    assert response.json() == {"c": "value"}

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])

